INSERT INTO leftover_repurposing_rules (id, leftover_type, title, description, instructions, recipe_id, display_order) VALUES
  ('75c04071-e7dd-5dd1-b0b1-75012d498296', 'dal', 'Dal Paratha', 'Knead leftover dal into atta for soft, protein-rich parathas.', '["Mix 1 cup leftover dal with 2 cups atta, a pinch of ajwain, chopped coriander and salt.", "Knead into a soft dough, adding water only if needed.", "Roll out and cook on a hot tawa with a little ghee."]'::jsonb, 'fe538bf5-ca17-504b-9fc4-e0fee19b6616', 0),
  ('4657e0c9-d09f-5e55-b274-b713437b482c', 'dal', 'Dal Chilla', 'Thicken leftover dal with besan and make savoury pancakes.', '["Whisk leftover dal with 3-4 tbsp besan, chopped onion and green chilli into a pourable batter.", "Spread on a hot greased tawa and cook until golden on both sides."]'::jsonb, '4f1828e6-c6e9-59c9-a4fc-b122f212d937', 1),
  ('7d4112ed-911d-5bbf-b016-57c878a0e152', 'dal', 'Dal Khichdi', 'Simmer leftover dal with rice into a quick one-pot khichdi.', '["Add leftover dal and a little water to cooked rice (or rinsed raw rice with more water).", "Simmer until creamy, temper with ghee and cumin."]'::jsonb, 'f2c89bef-1087-55b4-9dfb-1941479b4c8a', 2),
  ('7d3ad29b-fdfa-5648-b7ab-0bae8a104305', 'rice', 'Lemon Rice', 'Cold rice is perfect for a tangy tempered lemon rice.', '["Temper mustard seeds, curry leaves, peanuts and turmeric in oil.", "Toss in the leftover rice and salt, then squeeze lemon juice over it."]'::jsonb, 'fc29c160-afe2-54e2-88de-c72476bc6015', 3),
  ('7a8eb825-d953-5e8e-ac50-1feead6ed8f9', 'rice', 'Veg Fried Rice', 'Day-old rice fries up without turning mushy.', '["Stir-fry garlic and chopped vegetables on high heat.", "Add the leftover rice, soy sauce and pepper and toss well."]'::jsonb, '36d62e42-b4dc-5c7d-bf8b-4050bd20385b', 4),
  ('ca993e0e-67c9-5ae3-9a93-2db3cfbe1b81', 'rice', 'Curd Rice', 'Mash leftover rice with curd and a quick tempering.', '["Mash rice lightly with curd, a splash of milk and salt.", "Pour over a tempering of mustard seeds, curry leaves and green chilli."]'::jsonb, '919e6b97-d81f-5b1e-bb66-0c8dacba4d84', 5),
  ('c19cd139-5aa2-5dc5-8c2a-e7d36d0e855e', 'rice', 'Rice Tikki', 'Bind leftover rice with potato into crisp patties.', '["Mash rice with a boiled potato, chopped onion, chilli, coriander and salt.", "Shape into patties and shallow fry until crisp."]'::jsonb, NULL, 6),
  ('68d3f70c-c62f-5972-894a-51511e45a0eb', 'sabzi', 'Stuffed Paratha', 'Mash dry sabzi and use it as a paratha stuffing.', '["Mash the leftover sabzi so there are no big chunks.", "Stuff into atta dough balls, roll gently and cook with ghee."]'::jsonb, '5f38a6be-e705-57b4-9d97-d228124a2679', 7),
  ('619441f8-6f3b-59fb-a193-a5d085018668', 'sabzi', 'Toasted Sandwich', 'Spread leftover sabzi between buttered bread and toast.', '["Butter two slices of bread and spread green chutney if you have it.", "Fill with leftover sabzi and some cheese, then grill or toast on a tawa."]'::jsonb, 'b5f7fac9-6f4d-5800-bf5a-2a0da60c8ce4', 8),
  ('5b4398d4-b0d4-5c12-9454-364497334d1b', 'sabzi', 'Sabzi Frankie', 'Roll leftover sabzi in a roti with onions and chutney.', '["Warm a roti or paratha.", "Fill with the reheated sabzi, sliced onion, chaat masala and chutney, and roll it up."]'::jsonb, NULL, 9),
  ('b1332959-f443-5f03-9ca7-271ae051725e', 'roti', 'Phodnichi Poli (Roti Upma)', 'Shred leftover rotis and toss with a poha-style tempering.', '["Tear rotis into small pieces.", "Temper mustard seeds, curry leaves, onion and turmeric, then toss in the roti pieces with a sprinkle of water."]'::jsonb, NULL, 10),
  ('aa95cee3-bb1e-5d6a-9d29-7fe52016c874', 'roti', 'Chilli Roti', 'Indo-Chinese style strips of roti with peppers and sauces.', '["Cut rotis into strips.", "Stir-fry garlic, onion and capsicum, add soy and chilli sauce, then toss the roti strips."]'::jsonb, NULL, 11),
  ('f86b1f53-d3ca-5504-bd48-957a83bc9d21', 'roti', 'Roti Pizza', 'Use a leftover roti as a quick thin-crust pizza base.', '["Spread ketchup or tomato puree on the roti and top with vegetables and cheese.", "Cook covered on a tawa on low heat until the cheese melts."]'::jsonb, NULL, 12),
  ('7f9906ca-e56b-5d67-bd04-b693559b8342', 'curry', 'Curry Pulao', 'Cook rice in leftover curry for a flavourful one-pot pulao.', '["Saute the leftover curry in a little ghee.", "Add rinsed rice and water (adjusting for the curry''s liquid) and cook until done."]'::jsonb, 'e3008ffb-c814-599a-b055-dd968917ef0a', 13),
  ('93a511e5-9008-56f8-b3dd-72e2ffb4fbfb', 'curry', 'Kathi Roll', 'Reduce leftover paneer or chicken curry until dry and roll it in a paratha.', '["Cook the curry on high heat until thick and dry.", "Fill a paratha with it, add onion, lemon and chutney, and roll."]'::jsonb, NULL, 14),
  ('399675ac-fde7-5e6a-b9e7-a591fd9abcc9', 'curry', 'Curry Bread Bowl', 'Serve leftover curry hot with toasted pav or bread.', '["Reheat the curry thoroughly until steaming hot.", "Toast pav with butter and serve alongside."]'::jsonb, NULL, 15),
  ('1e192c5a-b39e-5063-bd9f-299ea2bc989b', 'other', 'Paratha Stuffing', 'Most dry leftovers can be mashed into a paratha stuffing.', '["Mash the leftover, season with salt, chilli and coriander.", "Stuff into atta dough and cook with ghee."]'::jsonb, '5f38a6be-e705-57b4-9d97-d228124a2679', 16),
  ('89e68a3f-9107-5cc9-8fe8-38e70aeb03b3', 'other', 'Toasted Sandwich', 'Turn small leftovers into a sandwich filling.', '["Spread the reheated leftover between buttered bread slices.", "Toast on a tawa until golden."]'::jsonb, 'b5f7fac9-6f4d-5800-bf5a-2a0da60c8ce4', 17);
